  "product_description": {
    "description": {
      "text": "Sertraline hydrochloride tablets USP contains sertraline hydrochloride, an SSRI. Sertraline hydrochloride has a molecular weight of 342.7 and has the following chemical name: (1S-cis)-4-(3,4-dichlorophenyl)-1,2,3,4-tetrahydro-N-methyl-1-naphthalenamine hydrochloride. The empirical formula C 17H 17NCl 2•HCl is represented by the following structural formula: Sertraline hydrochloride USP is a white crystalline powder that is slightly soluble in water and isopropyl alcohol, and sparingly soluble in ethanol. Sertraline hydrochloride tablets, USP for oral administration are supplied as scored tablets containing 27.98 mg, 55.9 mg and 111.9 mg sertraline hydrochloride equivalent to 25 mg, 50 mg and 100 mg of sertraline and the following inactive ingredients: dibasic calcium phosphate dihydrate, hydroxypropyl cellulose, microcrystalline cellulose, magnesium stearate, ascorbic acid, opadry green (titanium dioxide, hypromellose 3cP, hypromellose 6cP, Macrogol/Peg 400, polysorbate 80, D&C Yellow #10 Aluminum Lake, and FD&C Blue # 2/Indigo Carmine Aluminum Lake for 25 mg tablet), opadry light blue (hypromellose 3cP, hypromellose 6cP, titanium dioxide, Macrogol/Peg 400, FD&C Blue #2/Indigo Carmine Aluminum Lake and polysorbate 80 for 50 mg tablet), opadry yellow (hypromellose 3cP, hypromellose 6cP, titanium dioxide, Macrogol/Peg 400, polysorbate 80, Iron Oxide Yellow, Iron oxide Red for 100 mg tablet) and sodium starch glycolate.",
      "truncated": false
    }
  },
  "approved_use_sections": {
    "indications_and_usage": {
      "text": "Sertraline hydrochloride tablets are indicated for the treatment of the following [See Clinical Studies (14)] : Major depressive disorder (MDD) Obsessive-compulsive disorder (OCD) Panic disorder (PD) Posttraumatic stress disorder (PTSD) Social anxiety disorder (SAD) Premenstrual dysphoric disorder (PMDD)",
      "truncated": false
    },
    "clinical_studies": {
      "text": "Efficacy of sertraline hydrochloride was established in the following trials: MDD: two short-term trials and one maintenance trials in adults [See Clinical Studies (14.1)]. OCD: three short-term trials in adults and one short-term trial in pediatric patients [See Clinical Studies (14.2)] . PD: three short-term trials and one maintenance trial in adults [See Clinical Studies (14.3)]. PTSD: two short-term trials and one maintenance trial in adults [See Clinical Studies (14.4)]. SAD: two short-term trials and one maintenance trial in adults [See Clinical Studies (14.5)]. PMDD: two short-term trials in adult female patients [See Clinical Studies (14.6)] .",
      "truncated": false
    }
  },
